// Renders the typed, fetch-based client in `shared/src/api/generated-client.ts`.
//
// The emitted module has no runtime dependencies: it uses the global `fetch`
// (or an injected one), takes the base URL and an auth-token provider as
// options, and types every operation's params / query / body / response from
// the manifest. Operations without a schema are typed `unknown`.

import { jsonSchemaToTs, propertyKey } from './typescript';
import type { ManifestRoute, JsonSchema } from './manifest';

export const CLIENT_HEADER = [
  '// Generated by scripts/generate-api-contract.ts from the backend route manifest.',
  '// Do not edit. Run `bun run api:generate` after changing a route or its schema.',
  '',
].join('\n');

function requiredNames(schema: JsonSchema | undefined): string[] {
  const req = schema?.['required'];
  return Array.isArray(req) ? (req as string[]) : [];
}

function hasProperties(schema: JsonSchema | undefined): boolean {
  const props = schema?.['properties'];
  return !!props && typeof props === 'object' && Object.keys(props as object).length > 0;
}

function pathParamType(route: ManifestRoute, name: string): string {
  const props = (route.params?.['properties'] ?? {}) as Record<string, JsonSchema>;
  return props[name] ? jsonSchemaToTs(props[name]) : 'string';
}

interface InputMember {
  readonly name: 'params' | 'query' | 'body';
  readonly optional: boolean;
  readonly type: string;
}

/** The members of one operation's input, with types indented for a block at `indent`. */
export function operationInputMembers(route: ManifestRoute, indent: string): InputMember[] {
  const members: InputMember[] = [];
  if (route.pathParams.length > 0) {
    const fields = route.pathParams
      .map((name) => `${propertyKey(name)}: ${pathParamType(route, name)};`)
      .join(' ');
    members.push({ name: 'params', optional: false, type: `{ ${fields} }` });
  }
  if (route.query && hasProperties(route.query)) {
    const queryRequired = requiredNames(route.query).length > 0;
    members.push({
      name: 'query',
      optional: !queryRequired,
      type: jsonSchemaToTs(route.query, indent),
    });
  }
  if (route.body) {
    const bodyRequired = requiredNames(route.body).length > 0 || route.body['type'] !== 'object';
    members.push({
      name: 'body',
      optional: !bodyRequired,
      type: jsonSchemaToTs(route.body, indent),
    });
  }
  return members;
}

/** True when the whole `input` may be omitted (no path params and no required query or body). */
export function inputOmittable(members: readonly InputMember[]): boolean {
  return members.every((m) => m.optional);
}

function renderInput(route: ManifestRoute): { lines: string[]; optional: boolean } {
  const members = operationInputMembers(route, '      ');
  if (members.length === 0) return { lines: ['    input: undefined;'], optional: false };
  const optional = inputOmittable(members);
  const lines = [`    input${optional ? '?' : ''}: {`];
  for (const m of members) {
    lines.push(`      ${m.name}${m.optional ? '?' : ''}: ${m.type};`);
  }
  lines.push('    };');
  return { lines, optional };
}

function responseType(route: ManifestRoute): string {
  return route.response ? jsonSchemaToTs(route.response) : 'unknown';
}

export function renderGeneratedClient(routes: readonly ManifestRoute[]): string {
  const operations: string[] = [];
  const table: string[] = [];
  for (const route of routes) {
    const input = renderInput(route);
    operations.push(
      [
        `  ${JSON.stringify(route.key)}: {`,
        ...input.lines,
        `    response: ${responseType(route)};`,
        `    auth: ${JSON.stringify(route.auth)};`,
        '  };',
      ].join('\n'),
    );
    table.push(
      `  ${JSON.stringify(route.key)}: { method: ${JSON.stringify(route.method)}, path: ${JSON.stringify(route.path)} },`,
    );
  }

  return [
    CLIENT_HEADER,
    '/** Every route in the backend, keyed by `METHOD /openapi/path`. */',
    'export interface KoryApiOperations {',
    operations.join('\n'),
    '}',
    '',
    'export type KoryApiOperationKey = keyof KoryApiOperations;',
    '',
    '/** Arguments for `request(key, ...)`: omitted entirely when the operation takes no input. */',
    'export type KoryApiRequestArgs<K extends KoryApiOperationKey> =',
    '  KoryApiOperations[K] extends { input: infer I }',
    '    ? undefined extends I',
    '      ? [input?: Exclude<I, undefined>]',
    '      : [input: I]',
    '    : [];',
    '',
    '/** Result type for `request(key, ...)`. Responses are the full JSON body (the `ok`/`data` envelope included). */',
    'export type KoryApiResponse<K extends KoryApiOperationKey> = KoryApiOperations[K]["response"];',
    '',
    'export const KORY_API_ROUTES: Record<KoryApiOperationKey, { method: string; path: string }> = {',
    table.join('\n'),
    '};',
    '',
    'export interface KoryApiClientOptions {',
    '  /** Backend origin, e.g. `http://localhost:3001`. A trailing slash is ignored. */',
    '  baseUrl: string;',
    '  /** Supplies the local session bearer token. Called per request; return null to send none. */',
    '  getAuthToken?: () => string | null | undefined | Promise<string | null | undefined>;',
    '  /** Replaces the global `fetch` (tests, custom transports). */',
    '  fetch?: typeof fetch;',
    '}',
    '',
    'export class KoryApiError extends Error {',
    '  readonly status: number;',
    '  readonly body: unknown;',
    '  readonly key: string;',
    '  constructor(key: string, status: number, body: unknown) {',
    '    super(`${key} failed with HTTP ${status}`);',
    "    this.name = 'KoryApiError';",
    '    this.key = key;',
    '    this.status = status;',
    '    this.body = body;',
    '  }',
    '}',
    '',
    'export interface KoryApiClient {',
    '  request<K extends KoryApiOperationKey>(',
    '    key: K,',
    '    ...args: KoryApiRequestArgs<K>',
    '  ): Promise<KoryApiResponse<K>>;',
    '}',
    '',
    'export function createKoryApiClient(options: KoryApiClientOptions): KoryApiClient {',
    "  const baseUrl = options.baseUrl.replace(/\\/+$/, '');",
    '  const fetchImpl = options.fetch ?? globalThis.fetch;',
    '  return {',
    '    async request<K extends KoryApiOperationKey>(key: K, ...args: KoryApiRequestArgs<K>) {',
    '      const input = (args[0] ?? undefined) as { params?: Record<string, unknown>; query?: Record<string, unknown>; body?: unknown } | undefined;',
    '      const route = KORY_API_ROUTES[key];',
    '      const path = route.path.replace(/\\{([^}]+)\\}/g, (_match, name: string) => {',
    '        const value = input?.params?.[name];',
    '        if (value === undefined || value === null) throw new Error(`${key} requires path parameter ${name}`);',
    '        return encodeURIComponent(String(value));',
    '      });',
    '      const search = new URLSearchParams();',
    '      for (const [name, value] of Object.entries(input?.query ?? {})) {',
    '        if (value === undefined || value === null) continue;',
    '        const values = Array.isArray(value) ? value : [value];',
    '        for (const item of values) {',
    "          search.append(name, typeof item === 'object' ? JSON.stringify(item) : String(item));",
    '        }',
    '      }',
    '      const query = search.toString();',
    "      const headers: Record<string, string> = { accept: 'application/json' };",
    '      const token = options.getAuthToken ? await options.getAuthToken() : null;',
    "      if (token) headers['authorization'] = `Bearer ${token}`;",
    '      const init: RequestInit = { method: route.method, headers };',
    '      if (input?.body !== undefined) {',
    "        headers['content-type'] = 'application/json';",
    '        init.body = JSON.stringify(input.body);',
    '      }',
    "      const url = `${baseUrl}${path}${query ? `?${query}` : ''}`;",
    '      const response = await fetchImpl(url, init);',
    '      const text = await response.text();',
    '      let body: unknown = undefined;',
    '      if (text.length > 0) {',
    '        try {',
    '          body = JSON.parse(text);',
    '        } catch {',
    '          body = text;',
    '        }',
    '      }',
    '      if (!response.ok) throw new KoryApiError(key, response.status, body);',
    '      return body as KoryApiResponse<K>;',
    '    },',
    '  };',
    '}',
    '',
  ].join('\n');
}
